# generated by aitest
import datetime
import tomli

TOML = '''
s = "str"
i = 7
f = 1.5
b = true
odt = 1979-05-27T07:32:00Z
ld = 1979-05-27
time = 07:32:00
arr = [1, 2, 3]
[tbl]
k = "v"
'''


def test_type_mapping():
    d = tomli.loads(TOML)
    assert isinstance(d["s"], str)
    assert isinstance(d["i"], int) and not isinstance(d["i"], bool)
    assert isinstance(d["f"], float)
    assert isinstance(d["b"], bool)
    assert isinstance(d["odt"], datetime.datetime)
    assert isinstance(d["ld"], datetime.date)
    assert isinstance(d["time"], datetime.time)
    assert isinstance(d["arr"], list) and d["arr"] == [1, 2, 3]
    assert isinstance(d["tbl"], dict) and d["tbl"]["k"] == "v"
